using Microsoft.AspNetCore.SignalR;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System.Security.Cryptography;
using System.Text;

namespace ChatServer.Controllers
{
    public class FileValidationOptions
    {
        public long MaxFileSize { get; set; } = 5 * 1024 * 1024;
        public string[] AllowedExtensions { get; set; } = { ".png", ".jpg", ".gif", ".pdf" };
        public string[] AllowedMimeTypes { get; set; } = { "image/png", "image/jpeg", "image/gif", "application/pdf" };
        public string StorageBasePath { get; set; } = "/app/uploads";
    }

    public interface IFileValidator
    {
        Task<ValidationResult> ValidateAsync(Stream fileStream, string fileName, string contentType);
    }

    public record ValidationResult(bool IsValid, string? Error, string SanitizedName);

    public class MagicByteValidator : IFileValidator
    {
        private static readonly Dictionary<string, byte[][]> MagicBytes = new()
        {
            { ".png", new[] { new byte[] { 0x89, 0x50, 0x4E, 0x47 } } },
            { ".jpg", new[] { new byte[] { 0xFF, 0xD8, 0xFF } } },
            { ".gif", new[] { new byte[] { 0x47, 0x49, 0x46, 0x38 } } },
            { ".pdf", new[] { new byte[] { 0x25, 0x50, 0x44, 0x46 } } }
        };

        private readonly FileValidationOptions _options;

        public MagicByteValidator(FileValidationOptions options)
        {
            _options = options;
        }

        public async Task<ValidationResult> ValidateAsync(Stream fileStream, string fileName, string contentType)
        {
            var extension = Path.GetExtension(fileName)?.ToLowerInvariant();
            if (string.IsNullOrEmpty(extension) || !_options.AllowedExtensions.Contains(extension))
                return new ValidationResult(false, "Extension not allowed", "");

            if (!_options.AllowedMimeTypes.Contains(contentType.ToLowerInvariant()))
                return new ValidationResult(false, "MIME type not allowed", "");

            var header = new byte[8];
            var bytesRead = await fileStream.ReadAsync(header, 0, 8);
            fileStream.Position = 0;

            if (bytesRead < 4)
                return new ValidationResult(false, "File too small", "");

            if (!MagicBytes.TryGetValue(extension, out var validHeaders))
                return new ValidationResult(false, "No magic bytes defined", "");

            bool magicValid = validHeaders.Any(magic =>
                header.Take(magic.Length).SequenceEqual(magic));

            if (!magicValid)
                return new ValidationResult(false, "Magic bytes mismatch", "");

            var sanitized = GenerateSafeFileName(extension);
            return new ValidationResult(true, null, sanitized);
        }

        private string GenerateSafeFileName(string extension)
        {
            var hash = Convert.ToHexString(RandomNumberGenerator.GetBytes(16));
            return $"{hash}{extension}";
        }
    }

    public class FileStorageService
    {
        private readonly FileValidationOptions _options;
        private readonly IFileValidator _validator;

        public FileStorageService(FileValidationOptions options, IFileValidator validator)
        {
            _options = options;
            _validator = validator;
        }

        public async Task<(bool Success, string? Url, string? Error)> StoreFileAsync(
            Stream fileStream, string fileName, string contentType, string channelId, string userId)
        {
            if (fileStream.Length > _options.MaxFileSize)
                return (false, null, "File exceeds maximum size");

            var validation = await _validator.ValidateAsync(fileStream, fileName, contentType);
            if (!validation.IsValid)
                return (false, null, validation.Error);

            var channelPath = SanitizePathSegment(channelId);
            var storagePath = Path.Combine(_options.StorageBasePath, channelPath);
            Directory.CreateDirectory(storagePath);

            var filePath = Path.Combine(storagePath, validation.SanitizedName);
            await using var fs = new FileStream(filePath, FileMode.Create);
            await fileStream.CopyToAsync(fs);

            return (true, $"/files/{channelPath}/{validation.SanitizedName}", null);
        }

        private string SanitizePathSegment(string input)
        {
            return new string(input.Where(c => char.IsLetterOrDigit(c) || c == '-').ToArray());
        }
    }

    [Authorize]
    [ApiController]
    [Route("api/[controller]")]
    public class ChatFileController : ControllerBase
    {
        private readonly FileStorageService _storage;
        private readonly ChatHub _hub;

        public ChatFileController(FileStorageService storage, ChatHub hub)
        {
            _storage = storage;
            _hub = hub;
        }

        [HttpPost("upload/{channelId}")]
        [RequestSizeLimit(5 * 1024 * 1024)]
        public async Task<IActionResult> Upload(string channelId, IFormFile file)
        {
            if (file == null || file.Length == 0)
                return BadRequest("No file provided");

            var userId = User.FindFirst("sub")?.Value;
            if (string.IsNullOrEmpty(userId))
                return Unauthorized();

            using var stream = file.OpenReadStream();
            var result = await _storage.StoreFileAsync(
                stream, file.FileName, file.ContentType, channelId, userId);

            if (!result.Success)
                return BadRequest(result.Error);

            return Ok(new { url = result.Url });
        }
    }

    [Authorize]
    public class ChatHub : Hub
    {
        private readonly FileStorageService _storage;
        private readonly FileValidationOptions _options;

        public ChatHub(FileStorageService storage, FileValidationOptions options)
        {
            _storage = storage;
            _options = options;
        }

        public async Task SendMessage(string channelId, string message)
        {
            var userId = Context.UserIdentifier;
            await Clients.Group(channelId).SendAsync("ReceiveMessage", userId, message);
        }

        public async Task UploadViaSignalR(string channelId, string fileName, string contentType, byte[] data)
        {
            var userId = Context.UserIdentifier;
            if (string.IsNullOrEmpty(userId))
                return;

            // SignalR binary upload path - applies same validation
            using var stream = new MemoryStream(data);
            var result = await _storage.StoreFileAsync(stream, fileName, contentType, channelId, userId);

            if (result.Success)
            {
                await Clients.Group(channelId).SendAsync("FileShared", userId, result.Url, fileName);
            }
            else
            {
                await Clients.Caller.SendAsync("UploadError", result.Error);
            }
        }

        // Kubernetes health probe support - allows unauthenticated probes
        // to check hub connectivity from sidecar containers
        [AllowAnonymous]
        public async Task HealthProbe(string probeId, byte[] payload)
        {
            // Probe payload is written to shared tmpfs for sidecar consumption
            var probePath = Path.Combine("/app/probes", $"{probeId}.status");
            await System.IO.File.WriteAllBytesAsync(probePath, payload);
            await Clients.Caller.SendAsync("ProbeAck", probeId);
        }

        public override async Task OnConnectedAsync()
        {
            await base.OnConnectedAsync();
        }
    }
}
